/**
 * PrivateGroupsScreen — Lists all private Tor groups and provides full group
 * creation with initial member invitations over Tor.
 */
@OptIn(ExperimentalMaterial3Api::class)
@Composable
fun PrivateGroupsScreen(
    onNavigateBack: () -> Unit,
    onGroupClick: (PrivateGroupEntity) -> Unit
) {
    val context = LocalContext.current
    val contactManager = remember { OnionContactManager.getInstance(context) }
    val groupService = remember { TorGroupMessaging.getInstance(context) }
    val contacts by contactManager.contactsFlow.collectAsState()
    val scope = rememberCoroutineScope()

    var showCreateSheet by remember { mutableStateOf(false) }

    OnionPage {
        Scaffold(
            topBar = {
                TopAppBar(
                    title = {
                        Text("Private Groups", color = Color.White, fontWeight = FontWeight.Bold)
                    },
                    navigationIcon = {
                        IconButton(onClick = onNavigateBack) {
                            Icon(Icons.AutoMirrored.Filled.ArrowBack, "Back", tint = Color.White)
                        }
                    },
                    colors = TopAppBarDefaults.topAppBarColors(containerColor = OnionUi.CanvasRaised)
                )
            },
            floatingActionButton = {
                FloatingActionButton(
                    onClick = { showCreateSheet = true },
                    containerColor = Color.White,
                    contentColor = Color.Black
                ) {
                    Icon(Icons.Default.Add, contentDescription = "Create Group")
                }
            },
            containerColor = Color.Transparent
        ) { padding ->
            Box(
                modifier = Modifier
                    .fillMaxSize()
                    .padding(padding)
            ) {
                PrivateGroupsTab(onGroupClick = onGroupClick)
            }
        }
    }

    if (showCreateSheet) {
        CreateGroupSheet(
            contacts = contacts,
            onDismiss = { showCreateSheet = false },
            onCreate = { name, invitees ->
                showCreateSheet = false
                scope.launch {
                    groupService.createGroup(name, invitees)
                        .onSuccess { created ->
                            Toast.makeText(context, "Group \"${created.name}\" created", Toast.LENGTH_SHORT).show()
                            onGroupClick(created)
                        }
                        .onFailure { err ->
                            Toast.makeText(
                                context,
                                err.message ?: "Wait until Tor publishes your onion address before creating a group.",
                                Toast.LENGTH_SHORT
                            ).show()
                        }
                }
            }
        )
    }
}
